#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long binpow(long long a, long long b) {
    long long res = 1;
    a %= MOD;
    while (b) {
        if (b & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);

    int n;
    cin >> n;

    long long inv100 = binpow(100, MOD - 2);
    vector<vector<long long>> prob(2 * n, vector<long long>(2 * n));

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            long long x;
            cin >> x;
            prob[i][j + n] = (x * inv100) % MOD;
        }

    if (n == 1) {
        cout << prob[0][1] << '\n';
        return 0;
    }

    int half1 = n / 2;
    int half2 = n - half1;

    vector<int> left1, left2, right;
    for (int i = 0; i < half1; ++i) left1.push_back(i);
    for (int i = half1; i < n; ++i) left2.push_back(i);
    for (int i = n; i < 2 * n; ++i) right.push_back(i);

    vector<int> subsets1, subsets2;
    int cnt1 = 0, cnt2 = 0;
    vector<int> idx0(1 << n, -1), idx1(1 << n, -1);

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == half1) {
            idx0[mask] = cnt1++;
            subsets1.push_back(mask);
        }
        if (__builtin_popcount(mask) == half2) {
            idx1[mask] = cnt2++;
            subsets2.push_back(mask);
        }
    }

    vector<int> f_arr(1 << cnt1), g_arr(1 << cnt2);
    vector<vector<bool>> adj(2 * n, vector<bool>(2 * n, false));

    auto compute = [&](vector<int>& out, const vector<int>& L, const vector<int>& R,
                       const vector<int>& subgs, vector<int>& idx_map) {
        vector<pair<int, int>> edges;
        for (int u : L) for (int v : R) edges.emplace_back(u, v);
        int m = edges.size();

        for (int mask = 0; mask < (1 << m); ++mask) {
            long long weight = 1;
            for (int i = 0; i < m; ++i) {
                int u = edges[i].first, v = edges[i].second;
                if (mask & (1 << i)) {
                    weight = (weight * prob[u][v]) % MOD;
                    adj[u][v] = true;
                } else {
                    weight = (weight * ((1 - prob[u][v] + MOD) % MOD)) % MOD;
                    adj[u][v] = false;
                }
            }

            int new_mask = 0;
            for (int gr : subgs) {
                vector<int> perm(L.begin(), L.end());
                vector<int> idxs;
                for (int i = 0; i < n; ++i)
                    if (gr & (1 << i)) idxs.push_back(i + n);

                sort(idxs.begin(), idxs.end());
                bool found = false;
                do {
                    bool ok = true;
                    for (size_t i = 0; i < perm.size(); ++i)
                        if (!adj[perm[i]][idxs[i]]) { ok = false; break; }
                    if (ok) { found = true; break; }
                } while (next_permutation(idxs.begin(), idxs.end()));
                if (found) new_mask |= (1 << idx_map[gr]);
            }
            out[new_mask] = (out[new_mask] + static_cast<int>(weight)) % MOD;
        }
    };

    compute(f_arr, left1, right, subsets1, idx0);
    compute(g_arr, left2, right, subsets2, idx1);

    for (int i = 0; i < cnt1; ++i)
        for (int mask = 0; mask < (1 << cnt1); ++mask)
            if (mask & (1 << i)) f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;

    long long ans = 0;
    vector<int> rev_map(cnt2);
    for (int i = 0; i < cnt2; ++i) {
        int mask = subsets2[i];
        int complement = ((1 << n) - 1) ^ mask;
        rev_map[i] = idx0[complement];
    }

    for (int mask = 1; mask < (1 << cnt2); ++mask) {
        int complement = (1 << cnt2) - 1 - mask;
        int rev_mask = 0;
        for (int i = 0; i < cnt2; ++i)
            if (complement & (1 << i)) rev_mask |= (1 << rev_map[i]);

        int inv_complement = ((1 << cnt1) - 1) ^ rev_mask;
        long long weight = (1 - f_arr[inv_complement] + MOD) % MOD;
        ans = (ans + weight * g_arr[mask]) % MOD;
    }

    cout << ans << '\n';
    return 0;
}
